277	    @Override
278	    @Transactional
279	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
280	        if (owner.isNew()) {
281	            LocalDate effectiveDate = owner.getRegistrationDate() != null
282	                ? owner.getRegistrationDate()
283	                : LocalDate.now();
284	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
285	            if (owner.getHouseholdId() == null) {
286	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
287	            }
288	            if (owner.getMemberId() == null) {
289	                owner.setMemberId(generateMemberId(owner));
290	            }
291	            if (owner.getNamesakeCount() == null) {
292	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
293	            }
294	            if (owner.getPossibleDuplicate() == null) {
295	                // A declared household member is not a suspected duplicate; otherwise flag it against
296	                // any existing member of the same household it collides with.
297	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
298	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
299	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
300	            }
301	            if (owner.getMembershipLevelCap() == null) {
302	                owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
303	            }
304	        }
305	        ownerRepository.save(owner);
306	        decorateWithHouseholdMemberCount(owner);
307	    }
308	
309	    /**
310	     * Count the existing owners (before this create) that share the given first and last name,
311	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
312	     */
313	    private int countNamesakes(String firstName, String lastName) {
314	        if (firstName == null || lastName == null) {
315	            return 0;
316	        }
317	        return (int) ownerRepository.findAll().stream()
318	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
319	                && lastName.equalsIgnoreCase(owner.getLastName()))
320	            .count();
321	    }
322	
323	    /**
324	     * Build a member id formatted {@code '<REGION><FY><HASH8><CHK>'}, where {@code REGION} is the
325	     * canonical region derived from the owner's postcode (falling back to the city-to-region
326	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}), {@code FY} is the
327	     * two-digit fiscal year (the fiscal year starting on 1 July) of the business-day-adjusted
328	     * registration date, {@code HASH8} is the first 8 upper-case hexadecimal characters of the
329	     * SHA-256 digest over the owner's normalized telephone concatenated with the last name (the
330	     * same region-and-hash identity), and {@code CHK} is a single Luhn check digit computed over
331	     * the digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}).
332	     * <p>
333	     * If the computed id collides with an existing owner's {@code memberId}, it is de-duplicated
334	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique
335	     * (e.g. {@code 'NSW261A2B3C4D7-2'}).
336	     */
337	    private String generateMemberId(Owner owner) {
338	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
339	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
340	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
341	        String fiscalYear = String.format("%02d", FiscalYear.startYear(owner.getRegistrationDate()) % 100);
342	        String body = region + fiscalYear + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
343	        String base = body + LuhnCheckDigit.compute(body);
344	
345	        Set<String> existingIds = ownerRepository.findAll().stream()
346	            .map(Owner::getMemberId)
347	            .filter(Objects::nonNull)
348	            .collect(Collectors.toSet());
349	        if (!existingIds.contains(base)) {
350	            return base;
351	        }
352	        int n = 2;
353	        while (existingIds.contains(base + "-" + n)) {
354	            n++;
355	        }
356	        return base + "-" + n;
357	    }
358	
359	    /**
360	     * Count the existing owners whose city matches the given city, compared case-insensitively,
361	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
362	     */
363	    private long countOwnersInCity(String city) {
364	        if (city == null) {
365	            return 0L;
366	        }
367	        return ownerRepository.findAll().stream()
368	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
369	            .count();
370	    }
371	
372	    @Override
373	    @Transactional(readOnly = true)
374	    public boolean isCityAtCapacity(String city) throws DataAccessException {
375	        return countOwnersInCity(city) >= CITY_CAPACITY;
376	    }
377	
378	    @Override
379	    @Transactional(readOnly = true)
380	    public boolean isCityApproachingCapacity(String city) throws DataAccessException {
381	        long count = countOwnersInCity(city);
382	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
383	    }
384	
385	    @Override
386	    @Transactional(readOnly = true)
387	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
388	        return countRegisteredToday() >= DAILY_CAPACITY;
389	    }
390	
391	    @Override
392	    @Transactional(readOnly = true)
393	    public boolean isBulkSignupDay() throws DataAccessException {
394	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
395	    }
396	
397	    /**
398	     * Count the owners whose registration date equals today's business day, used by the
399	     * daily create-limit and bulk-signup rules.
400	     */
401	    private long countRegisteredToday() {
402	        LocalDate businessDay = toBusinessDay(LocalDate.now());
403	        return ownerRepository.findAll().stream()
404	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
405	            .count();
406	    }
407	
408	    /**
409	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
410	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
411	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
412	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
413	     * derived from it (such as the member id's fiscal-year segment) and the per-day create-limit
414	     * all use the adjusted business day.
415	     */
416	    private static LocalDate toBusinessDay(LocalDate date) {
417	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
418	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
419	            || HOLIDAYS.contains(date)) {
420	            date = date.plusDays(1);
421	        }
422	        return date;
423	    }
424	
425	    @Override
426	    @Transactional(readOnly = true)
427	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
428	        String identityKey = owner.getIdentityKey();
429	        return ownerRepository.findAll().stream()
430	            .filter(existing -> existing != owner)
431	            .filter(existing -> !existing.isDeleted())
432	            .map(Owner::getIdentityKey)
433	            .anyMatch(identityKey::equals);
434	    }
435	
436	    /**
437	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
438	     * duplicate of, or {@code null} when there is none. A possible duplicate has a <em>different</em>
439	     * identity key from the existing owner (so it is not a hard duplicate) yet shares the Soundex code
440	     * of its last name and the same postcode, so it is worth flagging as a soft match. When several
441	     * existing owners match, the one with the lowest id is returned so the result is deterministic.
442	     * Computed once, at creation, to drive the read-only {@code possibleDuplicate}/
443	     * {@code possibleDuplicateOf} fields.
444	     */
445	    private Integer findPossibleDuplicateOf(Owner owner) {
446	        String identityKey = owner.getIdentityKey();
447	        String lastNameSoundex = Soundex.encode(owner.getLastName());
448	        String postcode = owner.getPostcode();
449	        return ownerRepository.findAll().stream()
450	            .filter(existing -> existing != owner && existing.getId() != null)
451	            .filter(existing -> !existing.isDeleted())
452	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
453	            .filter(existing -> lastNameSoundex.equals(Soundex.encode(existing.getLastName())))
454	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
455	            .map(Owner::getId)
456	            .min(Integer::compareTo)
457	            .orElse(null);
458	    }
459	
460	    /**
461	     * Compute the membership-level ceiling for a new owner, as required by the level-cap rule: a new
462	     * owner's {@code membershipLevel} cannot exceed one above the current maximum membership level
463	     * among its household members (existing owners sharing the same {@code householdId}, excluding
464	     * soft-deleted ones and the owner itself). Returns one above that maximum, or {@code null} when
465	     * the owner has no household id or no existing household member, in which case no cap applies.
466	     *
467	     * <p>Each existing member's level is read through {@link OwnerMapper#formatMembershipLevel},
468	     * after decorating the members with their current household member counts, so the maximum
469	     * reflects the same effective (already-capped) level the API returns for those members.
470	     */
471	    private Integer computeMembershipLevelCap(Owner newOwner) {
472	        String householdId = newOwner.getHouseholdId();
473	        if (householdId == null) {
474	            return null;
475	        }
476	        List<Owner> members = ownerRepository.findAll().stream()
477	            .filter(existing -> existing != newOwner && existing.getId() != null)
478	            .filter(existing -> !existing.isDeleted())
479	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
480	            .collect(Collectors.toList());
481	        if (members.isEmpty()) {
482	            return null;
483	        }
484	        decorateWithHouseholdMemberCount(members, members);
485	        int maxLevel = members.stream()
486	            .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
487	            .max()
488	            .getAsInt();
489	        return maxLevel + 1;
490	    }
491	
492	    @Override
493	    @Transactional(readOnly = true)
494	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
495	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
496	        return Sha256Hex.upperHexPrefix(key, 12);
497	    }
498	
499	    /**
500	     * Normalizes a household field (the last name) for the {@link #householdIdFor household id}
501	     * hash by trimming, collapsing runs of whitespace to a single space and lower-casing, so
502	     * differently cased or spaced but equivalent values yield the same household id.
503	     */
504	    private static String normalizeHouseholdValue(String value) {
505	        if (value == null) {
506	            return "";
507	        }
508	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
509	    }
510	
511	    /**
512	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
513	     * owners that share its {@code householdId}. Owners without a household id are left at a count
514	     * of zero.
515	     *
516	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
517	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
518	     */
519	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
520	        if (!owners.isEmpty()) {
521	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
522	                .filter(owner -> owner.getHouseholdId() != null)
523	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
524	            for (Owner owner : owners) {
525	                long size = owner.getHouseholdId() == null
526	                    ? 0L
527	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
528	                owner.setHouseholdMemberCount((int) size);
529	            }
530	        }
531	        return result;
532	    }
533	
534	    /**
535	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
536	     */
537	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
538	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
539	    }
540	
