308	     *
309	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
310	     * applied only where referenced via {@code qualifiedByName}.
311	     */
312	    @Named("formatTimezone")
313	    default String formatTimezone(Owner owner) {
314	        if (owner == null) {
315	            return null;
316	        }
317	        return LocalityResolver.timezone(formatLocality(owner));
318	    }
319	
320	    /**
321	     * Derives an owner's segment, as required by the API's read-only {@code ownerSegment} field:
322	     * {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'},
323	     * {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER} is {@code 'PREMIUM'}
324	     * when the owner's {@link #formatMembershipLevel membership level} is 3 or more, otherwise
325	     * {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the owner's {@link #formatLocality
326	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'} — a locality of
327	     * {@code 'UNKNOWN'} being exactly the case where no known region resolved.
328	     *
329	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
330	     * applied only where referenced via {@code qualifiedByName}.
331	     */
332	    @Named("formatOwnerSegment")
333	    default String formatOwnerSegment(Owner owner) {
334	        if (owner == null) {
335	            return null;
336	        }
337	        Integer level = formatMembershipLevel(owner);
338	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
339	        String area = LocalityResolver.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
340	        return tier + "_" + area;
341	    }
342	
343	    /**
344	     * Derives an owner's preferred contact channel, as required by the API's read-only
345	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
346	     * otherwise {@code 'PHONE'}.
347	     *
348	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
349	     * applied only where referenced via {@code qualifiedByName}.
350	     */
351	    @Named("formatContactPreference")
352	    default String formatContactPreference(Owner owner) {
353	        if (owner == null) {
354	            return null;
355	        }
356	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
357	    }
358	
359	    /**
360	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
361	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
362	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
363	     * no birth date was supplied (so the field is absent), or when no registration date is yet
364	     * known against which to compute the age.
365	     *
366	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
367	     * applied only where referenced via {@code qualifiedByName}.
368	     */
369	    @Named("formatAgeBand")
370	    default String formatAgeBand(Owner owner) {
371	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
372	            return null;
373	        }
374	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
375	        if (age < 18) {
376	            return "MINOR";
377	        }
378	        if (age < 65) {
379	            return "ADULT";
380	        }
381	        return "SENIOR";
382	    }
383	
384	    private static String initial(String name) {
385	        if (name == null || name.isEmpty()) {
386	            return "";
387	        }
388	        return Character.toUpperCase(name.charAt(0)) + ".";
389	    }
390	
391	    Owner toOwner(OwnerDto ownerDto);
392	
393	    @Mapping(target = "id", ignore = true)
394	    @Mapping(target = "pets", ignore = true)
395	    @Mapping(target = "addressLine1", ignore = true)
396	    @Mapping(target = "addressLine2", ignore = true)
397	    @Mapping(target = "address", ignore = true)
398	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
399	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
400	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
401	    Owner toOwner(OwnerFieldsDto ownerDto);
402	
403	    /**
404	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
405	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
406	     * title was supplied. This is the single place the inbound title conversion lives: it runs
407	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
408	     * update path, keeping both consistent.
409	     *
410	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
411	     * applied only where referenced via {@code qualifiedByName}.
412	     */
413	    @Named("mapTitle")
414	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
415	        return title == null ? null : title.getValue();
416	    }
417	
418	    /**
419	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
420	     * normalizing each. This is the single place the structured-field normalization rule lives: it
421	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
422	     * called directly on the update path to keep both create and update consistent.
423	     *
424	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
425	     * {@code address} is set to the {@link #composeAddress composed} effective address.
426	     */
427	    @AfterMapping
428	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
429	        if (ownerDto == null) {
430	            return;
431	        }
432	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
433	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
434	        owner.setAddress(composeAddress(ownerDto));
435	    }
436	
437	    /**
438	     * Composes the effective, normalized postal address for an owner from the supplied fields,
439	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
440	     * present, the result is the normalized {@code addressLine1} with the normalized
441	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
442	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
443	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
444	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
445	     */
446	    default String composeAddress(OwnerFieldsDto ownerDto) {
447	        if (ownerDto == null) {
448	            return null;
449	        }
450	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
451	        if (line1 != null && !line1.isEmpty()) {
452	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
453	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
454	        }
455	        return normalizeAddress(ownerDto.getAddress());
456	    }
457	
458	    /**
459	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
460	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
461	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
462	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
463	     * {@code '12 MAIN STREET'}.
464	     *
465	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
466	     * only where referenced via {@code qualifiedByName}.
467	     */
468	    @Named("normalizeAddress")
469	    default String normalizeAddress(String address) {
470	        return AddressNormalizer.normalize(address);
471	    }
472	
473	    /**
474	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
475	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
476	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
477	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
478	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
479	     *
480	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
481	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
482	     *
483	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
484	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
485	     */
486	    @Named("normalizeTelephone")
487	    default String normalizeTelephone(String telephone) {
488	        return TelephoneNormalizer.toE164(telephone);
489	    }
490	
491	    /**
492	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
493	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
494	     * guarantees any value present is a syntactically valid address.
495	     *
496	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
497	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
498	     * e.g. on update).
499	     */
500	    @Named("normalizeEmail")
501	    default String normalizeEmail(String email) {
502	        return email == null ? null : email.toLowerCase(Locale.ROOT);
503	    }
504	
505	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
506	
507	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
508	
509	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
510	        OwnerPageDto ownerPageDto = new OwnerPageDto();
511	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
512	        ownerPageDto.setPage(ownerPage.getNumber());
513	        ownerPageDto.setSize(ownerPage.getSize());
514	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
515	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
516	        return ownerPageDto;
517	    }
518	}
